CREATE DATABASE IF NOT EXISTS rknexora CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rknexora;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE colleges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,university VARCHAR(255),principal_name VARCHAR(150),coordinator_name VARCHAR(150),address TEXT,state VARCHAR(100),district VARCHAR(100),pincode VARCHAR(10),logo VARCHAR(500),college_share DECIMAL(10,2) DEFAULT 0,rknexora_share DECIMAL(10,2) DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,email VARCHAR(191) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','admin','college') NOT NULL,college_id BIGINT UNSIGNED NULL,status ENUM('active','inactive','blocked') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_users_college FOREIGN KEY(college_id) REFERENCES colleges(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE sectors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sector_name VARCHAR(150) NOT NULL UNIQUE,status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE domains (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sector_id BIGINT UNSIGNED NOT NULL,domain_name VARCHAR(150) NOT NULL,fee DECIMAL(10,2) DEFAULT 0,duration_hours INT UNSIGNED DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_domain_sector(sector_id,domain_name),FOREIGN KEY(sector_id) REFERENCES sectors(id)) ENGINE=InnoDB;
CREATE TABLE students (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,college_id BIGINT UNSIGNED NOT NULL,registration_number VARCHAR(100) NOT NULL UNIQUE,student_id VARCHAR(50) UNIQUE,name VARCHAR(150),father_name VARCHAR(150),gender ENUM('male','female','other'),dob DATE,programme VARCHAR(150),major_subject VARCHAR(150),session VARCHAR(20),semester VARCHAR(20),mobile VARCHAR(20),email VARCHAR(191) UNIQUE,photo VARCHAR(500),registration_date DATE,internship_status ENUM('preloaded','registered','active','completed','blocked') DEFAULT 'preloaded',payment_status ENUM('pending','paid','failed','refunded') DEFAULT 'pending',username VARCHAR(100) UNIQUE,password_hash VARCHAR(255),academics_json JSON,domain_id BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(college_id) REFERENCES colleges(id),FOREIGN KEY(domain_id) REFERENCES domains(id),INDEX idx_students_registration(registration_number),INDEX idx_students_student_id(student_id),INDEX idx_students_college_session_semester(college_id,session,semester)) ENGINE=InnoDB;
CREATE TABLE mentors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,employee_id VARCHAR(50) NOT NULL UNIQUE,designation VARCHAR(100),department VARCHAR(100),specialization VARCHAR(255),mobile VARCHAR(20),email VARCHAR(191) NOT NULL UNIQUE,qualification VARCHAR(255),profile_photo VARCHAR(500),password_hash VARCHAR(255),status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE mentor_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mentor_id BIGINT UNSIGNED NOT NULL,domain_id BIGINT UNSIGNED NOT NULL,college_id BIGINT UNSIGNED NOT NULL,session VARCHAR(20) NOT NULL,semester VARCHAR(20) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(mentor_id) REFERENCES mentors(id),FOREIGN KEY(domain_id) REFERENCES domains(id),FOREIGN KEY(college_id) REFERENCES colleges(id),UNIQUE KEY uq_mentor_assignment(mentor_id,domain_id,college_id,session,semester),INDEX idx_ma_scope(college_id,session,semester)) ENGINE=InnoDB;
CREATE TABLE modules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,domain_id BIGINT UNSIGNED NOT NULL,module_number INT UNSIGNED NOT NULL,module_name VARCHAR(255) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(domain_id) REFERENCES domains(id),UNIQUE KEY uq_module(domain_id,module_number)) ENGINE=InnoDB;
CREATE TABLE chapters (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_id BIGINT UNSIGNED NOT NULL,chapter_number INT UNSIGNED NOT NULL,chapter_name VARCHAR(255) NOT NULL,content_type ENUM('video','pdf','text','link') NOT NULL,content_url VARCHAR(500) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(module_id) REFERENCES modules(id),UNIQUE KEY uq_chapter(module_id,chapter_number)) ENGINE=InnoDB;
CREATE TABLE quizzes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chapter_id BIGINT UNSIGNED NOT NULL,questions_json JSON NOT NULL,passing_score DECIMAL(5,2) DEFAULT 40,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(chapter_id) REFERENCES chapters(id)) ENGINE=InnoDB;
CREATE TABLE assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chapter_id BIGINT UNSIGNED NOT NULL,question_text TEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(chapter_id) REFERENCES chapters(id)) ENGINE=InnoDB;
CREATE TABLE submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,assignment_id BIGINT UNSIGNED NOT NULL,file_url VARCHAR(500) NOT NULL,marks DECIMAL(5,2),status ENUM('submitted','approved','resubmit') DEFAULT 'submitted',mentor_comments TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(assignment_id) REFERENCES assignments(id),INDEX idx_submission_student(student_id,status)) ENGINE=InnoDB;
CREATE TABLE attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,login_time TIME,logout_time TIME,learning_hours DECIMAL(5,2) DEFAULT 0,status ENUM('present','absent','leave') DEFAULT 'absent',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),UNIQUE KEY uq_attendance(student_id,date),INDEX idx_attendance_date(date,status)) ENGINE=InnoDB;
CREATE TABLE logbook (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,activity TEXT NOT NULL,skills TEXT,hours_worked DECIMAL(5,2) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),UNIQUE KEY uq_logbook(student_id,date)) ENGINE=InnoDB;
CREATE TABLE live_projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,domain_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,report_url VARCHAR(500),status ENUM('submitted','approved','resubmit') DEFAULT 'submitted',mentor_feedback TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(domain_id) REFERENCES domains(id)) ENGINE=InnoDB;
CREATE TABLE internship_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,report_url VARCHAR(500) NOT NULL,status ENUM('submitted','approved','resubmit') DEFAULT 'submitted',mentor_remarks TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE assessments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,mentor_id BIGINT UNSIGNED NOT NULL,criteria_ratings_json JSON NOT NULL,overall_performance VARCHAR(100) NOT NULL,supervisor_remarks TEXT,status ENUM('draft','submitted','approved') DEFAULT 'submitted',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(mentor_id) REFERENCES mentors(id),UNIQUE KEY uq_assessment(student_id,mentor_id)) ENGINE=InnoDB;
CREATE TABLE certificates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL UNIQUE,certificate_number VARCHAR(100) NOT NULL UNIQUE,qr_code_url VARCHAR(500) NOT NULL,issued_date DATE NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(10,2) NOT NULL,transaction_id VARCHAR(150) NOT NULL UNIQUE,status ENUM('created','success','failed','refunded') DEFAULT 'created',gateway_payload JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),INDEX idx_payment_student_status(student_id,status)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED,details JSON,timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_entity(entity_type,entity_id),INDEX idx_audit_user_time(user_id,timestamp)) ENGINE=InnoDB;
CREATE TABLE chapter_completions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,chapter_id BIGINT UNSIGNED NOT NULL,status ENUM('unlocked','completed') DEFAULT 'unlocked',completed_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(chapter_id) REFERENCES chapters(id),UNIQUE KEY uq_completion(student_id,chapter_id)) ENGINE=InnoDB;
CREATE TABLE bulk_jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_uuid CHAR(36) NOT NULL UNIQUE,type ENUM('attendance','complete_learning','certificates','zip_documents') NOT NULL,status ENUM('queued','running','completed','failed') DEFAULT 'queued',progress DECIMAL(5,2) DEFAULT 0,processed INT UNSIGNED DEFAULT 0,total INT UNSIGNED DEFAULT 0,payload JSON,result JSON,error_message TEXT,created_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_bulk_status(status,created_at)) ENGINE=InnoDB;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(191) NOT NULL,token_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_reset_email_expiry(email,expires_at)) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS=1;
